(()=>{'use strict';const $=id=>document.getElementById(id),roles=['Lightweight interceptor','Armored heavyweight','Stealth specialist','Precision single-seater','Lightweight. Uncompromising. Gone.','All-terrain bruiser'];let current=4,vehicle,scene,renderer,camera,rimLight,ringMat,visible=true,orbitYaw=-.5,orbitVel=0,dragging=false,lastX=0;
function select(i){current=(i+6)%6;const d=KartModels.cars[current];$('hero-car').textContent=d.n;$('hero-role').textContent=roles[current];$('car-counter').textContent=String(current+1).padStart(2,'0')+' / 06';document.querySelector('.car-meta .eyebrow').textContent='SPECIALIST / '+String(current+1).padStart(2,'0');document.querySelectorAll('.machine').forEach((e,n)=>{e.classList.toggle('active',n===current);e.setAttribute('aria-pressed',String(n===current))});if(!scene)return;if(vehicle){scene.remove(vehicle);const gs=new Set(),ms=new Set();vehicle.traverse(n=>{if(n.geometry)gs.add(n.geometry);if(n.material)ms.add(n.material)});gs.forEach(g=>g.dispose());ms.forEach(m=>m.dispose())}vehicle=KartModels.create(d,d.c,'gloss');vehicle.rotation.y=orbitYaw;scene.add(vehicle);if(rimLight)rimLight.color.setHex(d.c);if(ringMat)ringMat.color.setHex(d.c)}
$('machine-list').innerHTML=KartModels.cars.map((d,i)=>`<button class="machine" style="--paint:#${d.c.toString(16).padStart(6,'0')}" aria-label="Preview ${d.n}" aria-pressed="false"><span class="number">${String(i+1).padStart(2,'0')} / SPECIALIST</span><i class="machine-color"></i><h3>${d.n}</h3><p>${roles[i]}</p><small>${d.ult} ↗</small></button>`).join('');document.querySelectorAll('.machine').forEach((e,i)=>e.onclick=()=>{select(i);document.querySelector('.showcase').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'})});$('prev-car').onclick=()=>select(current-1);$('next-car').onclick=()=>select(current+1);
try{const T=THREE;scene=new T.Scene();const canvas=$('showroom');renderer=new T.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputEncoding=T.sRGBEncoding;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;camera=new T.PerspectiveCamera(34,1,.1,80);camera.position.set(8,5.2,10);camera.lookAt(0,.5,0);scene.add(new T.HemisphereLight(0xdffaff,0x203429,.8));const light=new T.DirectionalLight(0xffffff,1.15);light.position.set(3,7,4);scene.add(light);rimLight=new T.DirectionalLight(0xb6ff3b,.85);rimLight.position.set(-4,3,-4);scene.add(rimLight);const deck=new T.Mesh(new T.CylinderGeometry(4.5,4.7,.15,80),new T.MeshStandardMaterial({color:0x192c2b,metalness:.7,roughness:.28}));deck.position.y=-.12;scene.add(deck);ringMat=new T.MeshBasicMaterial({color:0xb6ff3b,transparent:true,opacity:.75});const ring=new T.Mesh(new T.TorusGeometry(4.4,.03,6,100),ringMat);ring.rotation.x=Math.PI/2;ring.position.y=-.025;scene.add(ring);
 canvas.style.cursor='grab';
 canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;orbitVel=0;canvas.style.cursor='grabbing';canvas.setPointerCapture?.(e.pointerId)});
 canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX;lastX=e.clientX;orbitYaw+=dx*.012;orbitVel=dx*.008});
 const endDrag=()=>{dragging=false;canvas.style.cursor='grab'};canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);
 function resize(){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(canvas);resize();select(4);new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(canvas);const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;let last=0;function frame(t){requestAnimationFrame(frame);if(!visible||document.hidden||t-last<24)return;last=t;if(vehicle){if(!dragging){orbitYaw+=orbitVel+(reduced?0:.004);orbitVel*=.92}vehicle.rotation.y=orbitYaw}renderer.render(scene,camera)}requestAnimationFrame(frame)}catch{$('showroom-fallback').hidden=false;select(4)}
fetch('track-data.json').then(r=>r.json()).then(tracks=>document.querySelectorAll('[data-track]').forEach(el=>{const pts=tracks[+el.dataset.track].pts,xx=pts.map(p=>p[0]),zz=pts.map(p=>p[2]),xmin=Math.min(...xx),zmin=Math.min(...zz),span=Math.max(Math.max(...xx)-xmin,Math.max(...zz)-zmin);const path=pts.map(p=>`${20+(p[0]-xmin)/span*260},${20+(p[2]-zmin)/span*180}`).join(' ');el.innerHTML=`<svg viewBox="0 0 300 220" aria-label="Circuit outline"><polygon points="${path}" fill="none" stroke="#ffffff08" stroke-width="18" stroke-linejoin="round"/><polygon points="${path}" fill="none" stroke="var(--track)" stroke-width="3" stroke-linejoin="round"/></svg>`})).catch(()=>{});
})();
